<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Exams · Northvale Admin</title><?php $adminSection='exams'; ?><?= $this->include('admin/_styles') ?><style>.delete-btn{padding:8px 10px;border:1px solid #f0cbd2;border-radius:7px;background:#fff6f7;color:#b8324b;font-size:12px;cursor:pointer}.edit-btn{display:inline-block;padding:8px 11px;border-radius:7px;background:#eaf6ff;color:#168fd4;font-size:12px;font-weight:700;margin-right:5px}.error-box{margin-bottom:18px;padding:12px 14px;border-radius:8px;background:#fff0f0;color:#a32121}</style></head><body><div class="admin-app"><?php $username=session()->get('admin_username');$usertype=session()->get('admin_usertype'); ?><?= $this->include('admin/_sidebar') ?><main class="admin-main"><header class="admin-topbar"><div class="admin-top-title">Exams</div><div class="admin-search">⌕ <span>Search...</span><span style="margin-left:auto">⌘ K</span></div><div class="admin-pill">✦ AI insights</div><div style="font-size:20px;color:#778092">☼</div></header><div class="admin-content"><div class="admin-heading"><div><h1>Exam management</h1><p>Create, configure, and build assessment question sets.</p></div><a class="admin-btn" href="<?= site_url('admin/exams/new') ?>">＋ Create exam</a></div><?php if ($error): ?><div class="error-box"><?= esc($error) ?></div><?php endif; ?><?php if (!$exams): ?><div class="admin-card admin-empty">No exams have been created yet.</div><?php else: ?><div class="admin-table"><table><thead><tr><th>Exam</th><th>Schedule</th><th>Duration</th><th>Questions</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($exams as $exam): ?><tr><td><strong><?= esc($exam['title']) ?></strong><br><small style="color:#798196"><?= esc($exam['description']) ?></small></td><td><?= $exam['start_at'] ? esc($exam['start_at']) : 'Not scheduled' ?><br><?= $exam['end_at'] ? 'to ' . esc($exam['end_at']) : '' ?></td><td><?= esc((int)($exam['duration_seconds']/60)) ?> min<br><small><?= $exam['allow_multiple_submissions'] ? 'Multiple allowed' : 'Single submission' ?></small></td><td><?= esc($exam['question_count']) ?></td><td><?= esc($exam['status']) ?></td><td><a class="edit-btn" href="<?= site_url('admin/exams/' . $exam['id'] . '/edit') ?>">Edit</a><a class="admin-btn" style="padding:8px 11px;font-size:12px;margin-right:5px" href="<?= site_url('admin/exams/' . $exam['id'] . '/questions') ?>">Questions</a><form style="display:inline" method="post" action="<?= site_url('admin/exams/' . $exam['id'] . '/delete') ?>" onsubmit="return confirm('Delete this exam and its questions? This cannot be undone.');"><button class="delete-btn" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></main></div></body></html>
